const results = await Promise.all([
  tools.exec_command({cmd:"rtk git status --short","workdir":"/home/diogenes/Projects/twyne","yield_time_ms":10000,"max_output_tokens":2000}),
  tools.exec_command({cmd:"rtk find \"*robots*\"","workdir":"/home/diogenes/Projects/twyne","yield_time_ms":10000,"max_output_tokens":2000}),
  tools.exec_command({cmd:"rtk find \"*sitemap*\"","workdir":"/home/diogenes/Projects/twyne","yield_time_ms":10000,"max_output_tokens":2000}),
  tools.exec_command({cmd:"rtk grep -n -i \"noindex\\|canonical\\|sitemap\\|robots\\|og:url\\|<title>\" src public routes package.json vite.config.* 2>/dev/null","workdir":"/home/diogenes/Projects/twyne","yield_time_ms":10000,"max_output_tokens":6000})
]); results.forEach(r=>text(r.output));

const results = await Promise.all([
  tools.exec_command({cmd:"rtk read public/robots.txt","workdir":"/home/diogenes/Projects/twyne","yield_time_ms":10000,"max_output_tokens":3000}),
  tools.exec_command({cmd:"rtk read public/sitemap.xml","workdir":"/home/diogenes/Projects/twyne","yield_time_ms":10000,"max_output_tokens":5000}),
  tools.exec_command({cmd:"rtk grep -n -i -C 3 \"noindex\\|canonical\\|sitemap\\|robots\\|og:url\" src public","workdir":"/home/diogenes/Projects/twyne","yield_time_ms":10000,"max_output_tokens":8000}),
  tools.exec_command({cmd:"rtk grep -n -i \"siteUrl\\|PUBLIC_.*URL\\|twyne\\.love\\|baseUrl\\|metadata\" src package.json vite.config.ts qwik.config.ts 2>/dev/null","workdir":"/home/diogenes/Projects/twyne","yield_time_ms":10000,"max_output_tokens":8000})
]); results.forEach(r=>text(r.output));

const results = await Promise.all([
  tools.exec_command({cmd:"rtk proxy rg -n -i \"noindex|canonical|og:url|sitemap|robots\" src public","workdir":"/home/diogenes/Projects/twyne","yield_time_ms":10000,"max_output_tokens":10000}),
  tools.exec_command({cmd:"rtk find \"src/routes\"","workdir":"/home/diogenes/Projects/twyne","yield_time_ms":10000,"max_output_tokens":6000}),
  tools.exec_command({cmd:"rtk read package.json","workdir":"/home/diogenes/Projects/twyne","yield_time_ms":10000,"max_output_tokens":5000})
]); results.forEach(r=>text(r.output));

