import { component$ } from "@builder.io/qwik";
import { useDocumentHead, useLocation } from "@builder.io/qwik-city";
import {
  TWYNE_SITE_ORIGIN,
  canonicalUrl,
  isPrivateWorkspacePath,
} from "../../utils/seo";

/**
 * The RouterHead component is placed inside of the document `<head>` element.
 */
export const RouterHead = component$(() => {
  const head = useDocumentHead();
  const loc = useLocation();

  const ogImage = `${TWYNE_SITE_ORIGIN}/og-image.png`;
  const pageUrl = canonicalUrl(loc.url);

  // Keys (name or property) a route already declared — render site-wide
  // social defaults only when the route hasn't overridden them.
  const declared = new Set(
    head.meta.map((m) => m.property ?? m.name).filter(Boolean) as string[],
  );

  const title = head.title || "Twyne — An Editorial Room for Writers";
  const description =
    (head.meta.find((m) => m.name === "description")?.content as string) ??
    "Twyne is a writer-first editing room. Start from an interview, then draft with a brief, editorial personas, rubric review, and citation detection.";

  const socialDefaults: Array<{
    property?: string;
    name?: string;
    content: string;
  }> = [
    { property: "og:type", content: "website" },
    { property: "og:site_name", content: "Twyne" },
    { property: "og:title", content: title },
    { property: "og:description", content: description },
    { property: "og:url", content: pageUrl },
    { property: "og:image", content: ogImage },
    { property: "og:image:width", content: "1200" },
    { property: "og:image:height", content: "630" },
    { property: "og:image:alt", content: "Twyne — The Editorial Room" },
    { name: "twitter:card", content: "summary_large_image" },
    { name: "twitter:title", content: title },
    { name: "twitter:description", content: description },
    { name: "twitter:image", content: ogImage },
  ].filter((m) => !declared.has((m.property ?? m.name) as string));

  const privateWorkspace = isPrivateWorkspacePath(loc.url.pathname);

  return (
    <>
      <title>{title}</title>

      <link rel="canonical" href={pageUrl} />
      <meta name="viewport" content="width=device-width, initial-scale=1.0" />

      {/* Favicons / app icons */}
      <link rel="icon" type="image/svg+xml" href="/assets/griffin-mark.svg" />
      <link rel="icon" type="image/png" sizes="32x32" href="/icon-192.png" />
      <link rel="alternate icon" href="/favicon.ico" sizes="48x48" />
      <link
        rel="apple-touch-icon"
        sizes="180x180"
        href="/apple-touch-icon.png"
      />
      {/*
        Browser chrome color. `media` lets the browser pick without any JS —
        the light entry is the default and the dark one only applies when the
        OS asks for dark. The color tracks the OS scheme only; an explicit
        preset pick in the appearance settings is not mirrored here.
      */}
      <meta
        name="theme-color"
        media="(prefers-color-scheme: light)"
        content="#9c1a1f"
      />
      <meta
        name="theme-color"
        media="(prefers-color-scheme: dark)"
        content="#191714"
      />

      {/* Site-wide social defaults (routes may override any key) */}
      {socialDefaults.map((m) => (
        <meta key={m.property ?? m.name} {...m} />
      ))}

      {privateWorkspace && !declared.has("robots") && (
        <meta name="robots" content="noindex, nofollow, noarchive" />
      )}

      {head.meta.map((m) => (
        <meta key={m.key} {...m} />
      ))}

      {head.links.map((l) => (
        <link key={l.key} {...l} />
      ))}

      {head.styles.map((s) => (
        <style
          key={s.key}
          {...s.props}
          {...(s.props?.dangerouslySetInnerHTML
            ? {}
            : { dangerouslySetInnerHTML: s.style })}
        />
      ))}

      {head.scripts.map((s) => (
        <script
          key={s.key}
          {...s.props}
          {...(s.props?.dangerouslySetInnerHTML
            ? {}
            : { dangerouslySetInnerHTML: s.script })}
        />
      ))}
    </>
  );
});

export const TWYNE_SITE_ORIGIN = "https://twyne.love";

const PRIVATE_ROUTE_ROOTS = new Set([
  "analysis",
  "apparatus",
  "auth",
  "dossier",
  "editor",
  "library",
  "onboarding",
  "personas",
  "privacy-ledger",
  "revisions",
  "rubric",
  "settings",
  "signin",
]);

/** Canonicals always identify the public origin and never preserve tracking. */
export function canonicalUrl(url: URL): string {
  const path =
    url.pathname === "/" ? "/" : url.pathname.replace(/\/+$/, "") || "/";
  return new URL(path, TWYNE_SITE_ORIGIN).href;
}

/** Workspace and authentication shells are useful to users, not search results. */
export function isPrivateWorkspacePath(pathname: string): boolean {
  const root = pathname.replace(/^\/+/, "").split("/", 1)[0] ?? "";
  return PRIVATE_ROUTE_ROOTS.has(root);
}

export const TWYNE_HOME_STRUCTURED_DATA = {
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "WebSite",
      name: "Twyne",
      url: `${TWYNE_SITE_ORIGIN}/`,
      description:
        "A local-first editorial writing room for drafting with a brief, editorial personas, rubric review, and citation detection.",
    },
    {
      "@type": ["WebApplication", "SoftwareApplication"],
      name: "Twyne",
      url: `${TWYNE_SITE_ORIGIN}/`,
      image: `${TWYNE_SITE_ORIGIN}/og-image.png`,
      applicationCategory: "DesignApplication",
      operatingSystem: "Any",
      description:
        "A local-first writing workspace where a room of editorial personas reads from the writer's brief.",
      offers: {
        "@type": "Offer",
        price: "0",
        priceCurrency: "USD",
      },
    },
  ],
} as const;

/**
 * The writer's public profile. Canonical URL: /<handle>
 *
 * Reverse-chronological list of the writer's published "post" pieces. The
 * blog feed is separate (`/blog`), so a writer who is also an admin sees
 * their admin-authored posts on `/blog`, and everything else they've
 * published here.
 *
 * No auth. The profile (handle + display name + bio) is loaded first; the
 * piece list follows. A missing handle renders the same shape as an empty
 * profile, to avoid user enumeration.
 */

import { component$, useSignal, useVisibleTask$ } from "@builder.io/qwik";
import { type DocumentHead, useLocation, Link } from "@builder.io/qwik-city";
import { useConvexClient } from "../../utils/convex-context";
import { api } from "../../../convex/_generated/api";
import {
  WritingHeatmap,
  type ActivityDay,
} from "../../components/profile/writing-heatmap";

interface Profile {
  handle: string;
  displayName: string | null;
  bio: string | null;
  avatarUrl: string | null;
}

interface PublishedSummary {
  slug: string;
  ownerHandle: string | null;
  title: string;
  briefSummary: string | null;
  publishedAt: number;
}

interface ActivityStats {
  days: ActivityDay[];
  folioCount: number;
}

function daysWrittenInLast(days: ActivityDay[], window: number): number {
  const cutoff = Date.now() - window * 24 * 60 * 60 * 1000;
  return days.filter(
    (d) => new Date(d.day + "T00:00:00Z").getTime() >= cutoff,
  ).length;
}

export default component$(() => {
  const loc = useLocation();
  const clientSig = useConvexClient();
  const profile = useSignal<Profile | null>(null);
  const posts = useSignal<PublishedSummary[]>([]);
  const activity = useSignal<ActivityStats | null>(null);
  const isLoading = useSignal(true);
  const missing = useSignal(false);

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async () => {
    const handle = (loc.params.handle ?? "").toLowerCase();
    const client = clientSig.value;
    if (!client || !handle) {
      isLoading.value = false;
      return;
    }
    try {
      const [profileData, postData, activityData] = await Promise.all([
        client.query(api.profiles.getProfile, { handle }) as Promise<
          Profile | null
        >,
        client.query(api.published.listByHandle, { handle }) as Promise<
          PublishedSummary[]
        >,
        client.query(api.writingActivity.getPublicActivity, {
          handle,
        }) as Promise<ActivityStats | null>,
      ]);
      if (!profileData) {
        missing.value = true;
        isLoading.value = false;
        return;
      }
      profile.value = profileData;
      posts.value = postData;
