/** Public blog feed — admin-authored "blog" pieces, reverse-chron. */
export const listBlog = query({
  args: { limit: v.optional(v.number()) },
  handler: async (ctx, { limit }) => {
    const rows = await ctx.db
      .query("published")
      .withIndex("by_kind_publishedAt", (q) =>
