      slug: r.slug,
      ownerHandle: r.ownerHandle ?? null,
      title: r.title,
      authorName: r.authorName ?? null,
      briefSummary: r.briefSummary ?? null,
      publishedAt: r.publishedAt,
    }));
  },
});

