import { component$, useStore, useVisibleTask$, $ } from "@builder.io/qwik";
import { useNavigate, Link } from "@builder.io/qwik-city";
import type { DocumentHead } from "@builder.io/qwik-city";
import { AntiTabulaRasa } from "../../../components/onboarding/anti-tabula-rasa";
import { ConversationalInterview } from "../../../components/onboarding/conversational-interview";
import { ThemedDialog } from "../../../components/ui/themed-dialog";
import { useConvexClient } from "../../../utils/convex-context";
import { useAuth } from "../../../utils/auth-context";
import { api } from "../../../../convex/_generated/api";
import type {
  DossierAttachment,
  DossierProbe,
  DossierCheckResult,
  InterviewStyle,
  ProjectBrief,
  ProjectInterviewAnswers,
} from "../../../types";
import {
  hasConfiguredAiProvider,
  runClientDossierCheck,
} from "../../../utils/ai-client";
import {
  loadActiveFolioIdFromIdb,
  loadAiSettingsFromIdb,
  loadFolioContentFromIdb,
  loadWriterSettingsFromIdb,
} from "../../../utils/idb";
import {
  createProjectBrief,
  htmlToPlainText,
  loadDraftHtml,
  loadProjectBriefForFolio,
  saveProjectBriefForFolio,
  saveStartingMaterial,
} from "../../../utils/anti-tabula-rasa";
import { captureProductEvent } from "../../../utils/product-analytics";
import { dossierRouteClass } from "../../../utils/conversation-layout";
import { normalizeApplicationError } from "../../../utils/application-errors";

interface RefiningStore {
  brief: ProjectBrief | null;
  draftText: string;
  hydrated: boolean;
  style: InterviewStyle;
  dossierCheck: DossierCheckResult | null;
  dossierCheckLoading: boolean;
  dossierCheckError: string | null;
  formAnswers: Partial<ProjectInterviewAnswers> | null;
  formAttachments: DossierAttachment[];
  folioId: string | null;
  startOverOpen: boolean;
  startOverBusy: boolean;
}

/**
 * The brief refinery. Two modes:
 *   - **form** (default) — the existing AntiTabulaRasa with pre-filled answers.
 *   - **conversational** — chat with the AI about which fields have drifted.
 * Draft alignment is part of the live dossier preview: the room compares the
 * current manuscript with all seven fields, and the writer applies or dismisses
 * each proposed change in place.
 */
export default component$(() => {
  const nav = useNavigate();
  const auth = useAuth();
  const clientSig = useConvexClient();
  const store = useStore<RefiningStore>({
    brief: null,
    draftText: "",
    hydrated: false,
    style: "form",
    dossierCheck: null,
    dossierCheckLoading: false,
    dossierCheckError: null,
    formAnswers: null,
    formAttachments: [],
    folioId: null,
    startOverOpen: false,
    startOverBusy: false,
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async () => {
    const activeFolioId = await loadActiveFolioIdFromIdb();
    const requestedFolioId = new URLSearchParams(window.location.search).get(
      "folio",
    );
    store.folioId = requestedFolioId ?? activeFolioId;
    store.brief = await loadProjectBriefForFolio(store.folioId);
    store.draftText = store.folioId
      ? await loadFolioContentFromIdb(store.folioId)
      : await loadDraftHtml();
    const writer = await loadWriterSettingsFromIdb();
    store.style = writer.interviewStyle;
    store.hydrated = true;
  });

  const onFormSubmit = $(
    async (
      answers: ProjectInterviewAnswers,
      _existing?: string,
      _filename?: string,
      attachments?: DossierAttachment[],
      probes?: DossierProbe[],
    ) => {
      if (!store.brief || !store.folioId) return;
      const next = createProjectBrief(
        answers,
        store.brief,
        attachments,
        probes,
      );
      await saveProjectBriefForFolio(store.folioId, next);
      store.brief = next;
      void captureProductEvent("dossier_completed", { mode: "refine" });
      await nav("/editor/");
    },
  );

  const onConversationComplete = $(
    async ({
      answers,
      attachments,
      probes,
    }: {
      answers: ProjectInterviewAnswers;
      attachments: DossierAttachment[];
      probes: DossierProbe[];
    }) => {
      if (!store.brief || !store.folioId) return;
      const next = createProjectBrief(
        answers,
        store.brief,
        attachments,
        probes,
      );
      await saveProjectBriefForFolio(store.folioId, next);
      store.brief = next;
      void captureProductEvent("dossier_completed", { mode: "refine" });
      await nav("/editor/");
    },
  );

  const runDossierCheck = $(async (answers: ProjectInterviewAnswers) => {
    if (!store.brief) return;
    const draftText = htmlToPlainText(store.draftText).trim();
    if (!draftText) {
      store.dossierCheck = null;
      store.dossierCheckError =
        "There is no manuscript text to compare yet. Add some draft material, then try again.";
      return;
    }
    store.dossierCheckLoading = true;
    store.dossierCheckError = null;
    store.dossierCheck = null;
    try {
      const raw = await loadAiSettingsFromIdb();
      const settings = raw ?? {
        advancedMode: false,
        providers: [],
        defaultProviderId: null,
        perFeature: {},
        showProviderTags: false,
      };
      const currentBrief: ProjectBrief = {
        ...store.brief,
        answers,
        updatedAt: Date.now(),
      };
      const result = hasConfiguredAiProvider(settings)
        ? await runClientDossierCheck(
            { brief: currentBrief, draftText },
            settings,
          )
        : auth.value.user && clientSig.value
          ? await clientSig.value.action(api.agents.runDossierCheck, {
              brief: currentBrief,
              draftText,
            })
          : null;
      void nav("/editor/");
      return null;
    }
    return (
      <div class="min-h-screen flex items-center justify-center bg-[var(--color-paper)] px-5 py-12">
        <div class="w-full max-w-md">
          <div class="text-center">
            <p
              class="dept-label text-[var(--color-ink-light)]"
              style="font-family: var(--font-typewriter);"
            >
              The dossier is filed
            </p>
            <h1
              class="mt-2 text-[1.6rem] text-[var(--color-ink)]"
              style="font-family: var(--font-display);"
            >
              Keep your work across devices
            </h1>
            <p
              class="mt-2 text-[0.95rem] text-[var(--color-ink-light)]"
              style="font-family: var(--font-serif);"
            >
              Your brief is saved on this device. Sign in to back it up and pick
              up this folio anywhere, or head to the desk and do it later.
            </p>
          </div>

          <div class="mt-6 border-2 border-[var(--color-ink)] bg-[var(--color-paper)]">
            <AuthPanel />
          </div>

          <button
            onClick$={$(() => {
              void nav("/editor/");
            })}
            class="mt-5 w-full text-center text-[0.85rem] text-[var(--color-ink-light)] underline decoration-[var(--color-vermilion)] decoration-1 underline-offset-4 hover:text-[var(--color-ink)] focus-ring"
            style="font-family: var(--font-typewriter);"
          >
            Continue to the editor →
          </button>
        </div>
      </div>
    );
  }

  if (store.style === "conversational") {
    return (
      <div class={DOSSIER_ROUTE_CLASS}>
        <ConversationalInterview
          mode="first-run"
          chromeBackHref={store.folioId ? "/editor/" : "/"}
          chromeBackLabel={store.folioId ? "Back to desk" : "Back home"}
          onSwitchSurface$={$(() => {
            store.style = "form";
          })}
          initialMaterial={store.initialMaterial}
          onComplete$={({ answers, attachments, probes }) =>
            completeOnboarding$(
              answers,
              undefined,
              undefined,
              attachments,
              probes,
            )
          }
          onUseForm$={({ answers, attachments }) => {
            store.formAnswers = answers;
            store.formAttachments = attachments;
            store.style = "form";
          }}
        />
      </div>
    );
  }

  // The form surface owns the viewport, and files its own chrome into the
  // folio's top edge rather than stacking a page-wide bar above it.
  return (
    <div class={DOSSIER_ROUTE_CLASS}>
      <AntiTabulaRasa
        mode="first-run"
        chromeBackHref={store.folioId ? "/editor/" : "/"}
        chromeBackLabel={store.folioId ? "Back to desk" : "Back home"}
        onSwitchSurface$={$(() => {
          store.style = "conversational";
        })}
        initialAnswers={
          store.formAnswers as ProjectInterviewAnswers | null | undefined
        }
        initialAttachments={store.formAttachments}
        initialMaterial={store.initialMaterial}
        onSubmit$={completeOnboarding$}
      />
    </div>
  );
});

export const head: DocumentHead = {
  title: "Begin the dossier · Twyne",
  meta: [
    {
      name: "description",
      content:
        "Twyne's onboarding interview: the dossier the room will read from as you write.",
    },
  ],
};

