describe("mergeFormProbes", () => {
  test("preserves order, removes duplicate IDs and prompts, and caps the set", () => {
    const duplicatePrompt = {
      ...probe,
      id: "different-id",
      prompt: `  ${probe.prompt.toUpperCase()}  `,
