+    if (!isAnswered(merged[existingIndex]!) && isAnswered(probe)) {
+      merged[existingIndex] = probe;
+      indexById.set(probe.id, existingIndex);
+      indexByPrompt.set(promptKey, existingIndex);
+    }
+  }
