                      style={{ fontFamily: "var(--font-typewriter)" }}
                      title="Ask the room to synthesise the dossier now"
                    >
                      → Show me what you have
                    </button>
                  </ChatComposer>
                </div>
              </div>
            )}
          </>
        }
      />
    );
  },
);

