     1	import { component$, useStore, useVisibleTask$, $ } from "@builder.io/qwik";
     2	import { useNavigate, Link } from "@builder.io/qwik-city";
     3	import type { DocumentHead } from "@builder.io/qwik-city";
     4	import { AntiTabulaRasa } from "../../../components/onboarding/anti-tabula-rasa";
     5	import { ConversationalInterview } from "../../../components/onboarding/conversational-interview";
     6	import { ThemedDialog } from "../../../components/ui/themed-dialog";
     7	import { useConvexClient } from "../../../utils/convex-context";
     8	import { useAuth } from "../../../utils/auth-context";
     9	import { api } from "../../../../convex/_generated/api";
    10	import type {
    11	  DossierAttachment,
    12	  DossierProbe,
    13	  DossierCheckResult,
    14	  InterviewStyle,
    15	  ProjectBrief,
    16	  ProjectInterviewAnswers,
    17	} from "../../../types";
    18	import {
    19	  hasConfiguredAiProvider,
    20	  runClientDossierCheck,
    21	} from "../../../utils/ai-client";
    22	import {
    23	  loadActiveFolioIdFromIdb,
    24	  loadAiSettingsFromIdb,
    25	  loadFolioContentFromIdb,
    26	  loadWriterSettingsFromIdb,
    27	} from "../../../utils/idb";
    28	import {
    29	  createProjectBrief,
    30	  htmlToPlainText,
    31	  loadDraftHtml,
    32	  loadProjectBriefForFolio,
    33	  saveProjectBriefForFolio,
    34	  saveStartingMaterial,
    35	} from "../../../utils/anti-tabula-rasa";
    36	import { captureProductEvent } from "../../../utils/product-analytics";
    37	import { dossierRouteClass } from "../../../utils/conversation-layout";
    38	import { normalizeApplicationError } from "../../../utils/application-errors";
    39	import { dossierCheckUnavailableMessage } from "../../../utils/dossier-check";
    40	
    41	interface RefiningStore {
    42	  brief: ProjectBrief | null;
    43	  draftText: string;
    44	  hydrated: boolean;
    45	  style: InterviewStyle;
    46	  dossierCheck: DossierCheckResult | null;
    47	  dossierCheckLoading: boolean;
    48	  dossierCheckError: string | null;
    49	  formAnswers: Partial<ProjectInterviewAnswers> | null;
    50	  formAttachments: DossierAttachment[];
    51	  folioId: string | null;
    52	  startOverOpen: boolean;
    53	  startOverBusy: boolean;
    54	}
    55	
    56	/**
    57	 * The brief refinery. Two modes:
    58	 *   - **form** (default) — the existing AntiTabulaRasa with pre-filled answers.
    59	 *   - **conversational** — chat with the AI about which fields have drifted.
    60	 * Draft alignment is part of the live dossier preview: the room compares the
    61	 * current manuscript with all seven fields, and the writer applies or dismisses
    62	 * each proposed change in place.
    63	 */
    64	export default component$(() => {
    65	  const nav = useNavigate();
    66	  const auth = useAuth();
    67	  const clientSig = useConvexClient();
    68	  const store = useStore<RefiningStore>({
    69	    brief: null,
    70	    draftText: "",
    71	    hydrated: false,
    72	    style: "form",
    73	    dossierCheck: null,
    74	    dossierCheckLoading: false,
    75	    dossierCheckError: null,
    76	    formAnswers: null,
    77	    formAttachments: [],
    78	    folioId: null,
    79	    startOverOpen: false,
    80	    startOverBusy: false,
    81	  });
    82	
    83	  // eslint-disable-next-line qwik/no-use-visible-task
    84	  useVisibleTask$(async () => {
    85	    const activeFolioId = await loadActiveFolioIdFromIdb();
    86	    const requestedFolioId = new URLSearchParams(window.location.search).get(
    87	      "folio",
    88	    );
    89	    store.folioId = requestedFolioId ?? activeFolioId;
    90	    store.brief = await loadProjectBriefForFolio(store.folioId);
    91	    store.draftText = store.folioId
    92	      ? await loadFolioContentFromIdb(store.folioId)
    93	      : await loadDraftHtml();
    94	    const writer = await loadWriterSettingsFromIdb();
    95	    store.style = writer.interviewStyle;
    96	    store.hydrated = true;
    97	  });
    98	
    99	  const onFormSubmit = $(
   100	    async (
   101	      answers: ProjectInterviewAnswers,
   102	      _existing?: string,
   103	      _filename?: string,
   104	      attachments?: DossierAttachment[],
   105	      probes?: DossierProbe[],
   106	    ) => {
   107	      if (!store.brief || !store.folioId) return;
   108	      const next = createProjectBrief(
   109	        answers,
   110	        store.brief,
   111	        attachments,
   112	        probes,
   113	      );
   114	      await saveProjectBriefForFolio(store.folioId, next);
   115	      store.brief = next;
   116	      void captureProductEvent("dossier_completed", { mode: "refine" });
   117	      await nav("/editor/");
   118	    },
   119	  );
   120	
   121	  const onConversationComplete = $(
   122	    async ({
   123	      answers,
   124	      attachments,
   125	      probes,
   126	    }: {
   127	      answers: ProjectInterviewAnswers;
   128	      attachments: DossierAttachment[];
   129	      probes: DossierProbe[];
   130	    }) => {
   131	      if (!store.brief || !store.folioId) return;
   132	      const next = createProjectBrief(
   133	        answers,
   134	        store.brief,
   135	        attachments,
   136	        probes,
   137	      );
   138	      await saveProjectBriefForFolio(store.folioId, next);
   139	      store.brief = next;
   140	      void captureProductEvent("dossier_completed", { mode: "refine" });
   141	      await nav("/editor/");
   142	    },
   143	  );
   144	
   145	  const runDossierCheck = $(async (answers: ProjectInterviewAnswers) => {
   146	    if (!store.brief) return;
   147	    const draftText = htmlToPlainText(store.draftText).trim();
   148	    if (!draftText) {
   149	      store.dossierCheck = null;
   150	      store.dossierCheckError =
   151	        "There is no manuscript text to compare yet. Add some draft material, then try again.";
   152	      return;
   153	    }
   154	    store.dossierCheckLoading = true;
   155	    store.dossierCheckError = null;
   156	    store.dossierCheck = null;
   157	    try {
   158	      const raw = await loadAiSettingsFromIdb();
   159	      const settings = raw ?? {
   160	        advancedMode: false,
   161	        providers: [],
   162	        defaultProviderId: null,
   163	        perFeature: {},
   164	        showProviderTags: false,
   165	      };
   166	      const currentBrief: ProjectBrief = {
   167	        ...store.brief,
   168	        answers,
   169	        updatedAt: Date.now(),
   170	      };
   171	      const hasConfiguredProvider = hasConfiguredAiProvider(settings);
   172	      const result = hasConfiguredProvider
   173	        ? await runClientDossierCheck(
   174	            { brief: currentBrief, draftText },
   175	            settings,
   176	          )
   177	        : auth.value.user && clientSig.value
   178	          ? await clientSig.value.action(api.agents.runDossierCheck, {
   179	              brief: currentBrief,
   180	              draftText,
   181	            })
   182	          : null;
   183	      if (!result) {
   184	        store.dossierCheckError = dossierCheckUnavailableMessage(
   185	          hasConfiguredProvider,
   186	        );
   187	        return;
   188	      }
   189	      store.dossierCheck = result;
   190	    } catch (err) {
   191	      store.dossierCheckError = normalizeApplicationError(err, {
   192	        metadata: { feature: "dossier-check" },
   193	      }).message;
   194	    } finally {
   195	      store.dossierCheckLoading = false;
   196	    }
   197	  });
   198	
   199	  const applyObservation = $(
   200	    async (index: number, answers: ProjectInterviewAnswers) => {
   201	      if (!store.brief || !store.folioId) return;
   202	      const observation = store.dossierCheck?.observations[index];
   203	      if (!observation?.suggested) return;
   204	      const remaining =
   205	        store.dossierCheck?.observations.filter(
   206	          (_, observationIndex) => observationIndex !== index,
   207	        ) ?? [];
   208	      const next: ProjectBrief = {
   209	        ...store.brief,
   210	        answers,
   211	        updatedAt: Date.now(),
   212	      };
   213	      await saveProjectBriefForFolio(store.folioId, next);
