// eslint-disable-next-line qwik/no-use-visible-task
useVisibleTask$(async () => {
  const activeFolioId = await loadActiveFolioIdFromIdb();
  const requestedFolioId = new URLSearchParams(window.location.search).get(
    "folio",
  );
  store.folioId = requestedFolioId ?? activeFolioId;
  store.brief = await loadProjectBriefForFolio(store.folioId);
  store.draftText = store.folioId
    ? await loadFolioContentFromIdb(store.folioId)
    : await loadDraftHtml();
  const writer = await loadWriterSettingsFromIdb();
  store.style = writer.interviewStyle;
  store.hydrated = true;
});

const onFormSubmit = $(
  (
    answers: ProjectInterviewAnswers,
    _existing?: string,
    _filename?: string,
    attachments?: DossierAttachment[],
    probes?: DossierProbe[],
  ) => {
    if (!store.brief || !store.folioId) return;
    const next = createProjectBrief(
      answers,
      store.brief,
      attachments,
      probes,
    );
    void saveProjectBriefForFolio(store.folioId, next);
    void captureProductEvent("dossier_completed", { mode: "refine" });
    void nav("/editor/");
  },
);

const onConversationComplete = $(
  ({
    answers,
    attachments,
    probes,
  }: {
    answers: ProjectInterviewAnswers;
    attachments: DossierAttachment[];
    probes: DossierProbe[];
  }) => {
    if (!store.brief || !store.folioId) return;
    const next = createProjectBrief(
      answers,
      store.brief,
      attachments,
      probes,
    );
    void saveProjectBriefForFolio(store.folioId, next);
    void captureProductEvent("dossier_completed", { mode: "refine" });
    void nav("/editor/");
  },
);

const runDossierCheck = $(async () => {
  if (!store.brief) return;
  store.dossierCheckLoading = true;
  store.dossierCheckError = null;
  store.showDossierCheck = true;
  try {
    const raw = await loadAiSettingsFromIdb();
    const settings = raw ?? {
      advancedMode: false,
      providers: [],
      defaultProviderId: null,
      perFeature: {},
      showProviderTags: false,
    };
    if (!hasConfiguredAiProvider(settings)) {
      store.dossierCheckError =
        "Reading the draft needs a configured AI provider. Add one in Settings.";
      store.dossierCheckLoading = false;
      return;
    }
    const result = await runClientDossierCheck(
    /** True once we've tried, so re-entering the step doesn't re-ask. */
    probesRequested: boolean;
  }>({
    step: 0,
    answers: {
      ...DEFAULT_INTERVIEW_ANSWERS,
      ...initialAnswers,
    } as ProjectInterviewAnswers,
    attachments: initialAttachments ?? [],
    existingMaterial: initialMaterial ?? "",
    importedFilename: "",
    submitting: false,
    submitError: "",
    probes: [],
    probesLoading: false,
    probesRequested: false,
  });
  const clientSig = useConvexClient();

  const step = STEPS[store.step];
  if (!step) return null;
  const progress = Math.round(((store.step + 1) / STEPS.length) * 100);

  const goNext = $(async () => {
    // Read step from the reactive store at CALL time, not captured value
    const currentStep = store.step;
    const lastStep = currentStep === STEPS.length - 1;

    store.submitError = "";
    if (lastStep) {
      store.submitting = true;

      if (onSubmit$) {
        try {
          await onSubmit$(
            store.answers,
            store.existingMaterial,
            store.importedFilename,
            store.attachments,
            store.probes.filter((p) => p.answer !== undefined),
          );
        } catch (err) {
          store.submitError =
            (err as Error).message || "The dossier could not be saved.";
          store.submitting = false;
        }
        return;
      }

      window.dispatchEvent(
        new CustomEvent("twyne:submit-interview", {
          detail: {
            answers: store.answers,
            existingMaterial: store.existingMaterial,
            filename: store.importedFilename,
            attachments: store.attachments,
            probes: store.probes.filter((p) => p.answer !== undefined),
          },
        }),
      );
      return;
    }
    const next = currentStep + 1;
    store.step = next;
    // Fetch the follow-ups as the writer arrives, not on mount — they are
    // derived from answers that don't exist until this point.
    if (STEPS[next]?.kind === "probes") {
      void loadProbes();
    }
  });

  const handleFile = $(async (event: Event) => {
    const input = event.target as HTMLInputElement | null;
    const file = input?.files?.[0];
    if (!file) return;
    const raw = await file.text();
    store.existingMaterial = raw;
    store.importedFilename = file.name;
    if (input) input.value = "";
  });

  const clearMaterial = $(() => {
    store.existingMaterial = "";
    store.importedFilename = "";
  });

  const goBack = $(() => {
    if (store.step > 0) {
      store.step -= 1;
    }
  });

  /**
   * Ask the interviewer for follow-ups based on the answers filled in so far.
   *
   * The interview turn endpoint is reused rather than adding a bespoke one:
   * feeding it the form's answers as a transcript is exactly the situation it
   * already handles, and it means the form and the conversation generate
   * probes by the same rules.
   *
   * Failure is silent and the step becomes a plain "Continue". A form must
   * never strand someone behind a network call — these questions are a bonus,
   * not a gate.
   */
  const loadProbes = $(async () => {
    if (store.probesRequested || store.probesLoading) return;
    store.probesRequested = true;
    store.probesLoading = true;
    try {
      const transcript = [
        {
          author: "interviewer" as const,
          text: "Tell me about the piece — the form, the reader, the goal, the tone, the constraints, and how you'll know it landed.",
        },
        {
          author: "writer" as const,
          text: [
            `Working title: ${store.answers.workingTitle}`,
            `Format: ${store.answers.format}`,
            `Audience: ${store.answers.audience}`,
            `Goal: ${store.answers.goal}`,
            `Tone: ${store.answers.tone}`,
            `Constraints: ${store.answers.constraints}`,
            `Success signal: ${store.answers.successSignal}`,
          ].join("\n"),
        },
        {
          author: "writer" as const,
          text: "(ask me one sharp follow-up as a typed question — a choice, a scale, or a fill-in-the-blanks — about whichever of those answers is vaguest)",
        },
      ];

      const collected: DossierProbe[] = [];
      const settings = await loadAiSettingsFromIdb();
      const useByok = hasConfiguredAiProvider(settings) && settings;

      // Three sequential turns, each seeing the ones before, so the
      // interviewer doesn't ask the same question three ways.
      for (let i = 0; i < 3; i++) {
        const messages = [
          ...transcript,
          ...collected.flatMap((p) => [
            { author: "interviewer" as const, text: p.prompt },
            { author: "writer" as const, text: "(noted — ask another)" },
          ]),
        ];
        let result: InterviewTurnResult | null = null;
        if (useByok) {
          const client = await runClientInterviewTurn(
            { messages, mode: "first-run", currentBrief: null },
            settings,
          );
          result = client.ok ? client.value : null;
        } else if (clientSig.value) {
          result = (await clientSig.value.action(
            api.agents.runInterviewTurn,
            { messages, mode: "first-run", currentBrief: null },
          )) as InterviewTurnResult;
        }
        if (!result || result.kind !== "question" || !result.probe) break;
        collected.push(result.probe);
      }

      store.probes = collected;
    } catch (err) {
      reportApplicationDiagnostic("twyne:form:load-probes", err, {
        feature: "interview",
        operation: "form-probes",
      });
      store.probes = [];
    } finally {
      store.probesLoading = false;
    }
  });

  const answerFormProbe = $((answered: DossierProbe) => {
    store.probes = upsertProbe(store.probes, answered);
  });

  return (
    <div
      class="fixed inset-0 paper-sheet paper-foxed"
      style="z-index: var(--z-modal);"
      role="dialog"
      aria-modal="true"
      aria-labelledby="atr-title"
    >
      {/* Onboarding starts — let user click freely */}
      {store.submitting && (
        <div
          class="fixed top-4 right-4 flex items-center gap-2 rounded-full px-2.5 py-1"
          style="z-index: 9999; background: var(--color-paper-3); border: 1px solid var(--color-paper-3);"
        >
          <span
            class="block h-2 w-2 rounded-full"
            style="background: var(--color-vermilion); animation: pulse 1.5s ease-in-out infinite;"
          />
          <span
            class="text-[10px] tracking-wider text-[var(--color-ink-muted)]"
            style="font-family: var(--font-typewriter); text-transform: uppercase;"
          >

