    // eslint-disable-next-line qwik/no-use-visible-task
    useVisibleTask$(({ track }) => {
      track(() => store.messages.length);
      track(() => store.synthesis);
      const el = scrollerRef.value;
      if (el) el.scrollTop = el.scrollHeight;
    });

